verifyCmd:
node <<'VERIFYJS'
const sp = require('./shellSplit.js');
const S = JSON.stringify;
const eq = (got, want, m) => { if (S(got) !== S(want)) { console.error('FAIL', m, S(got), 'want', S(want)); process.exit(1); } };
eq(sp('a b c'), ['a', 'b', 'c'], 'basic');
eq(sp('  a   b  '), ['a', 'b'], 'whitespace runs');
eq(sp(''), [], 'empty line');
eq(sp('"a b"'), ['a b'], 'double quotes keep spaces');
eq(sp("'a b'"), ['a b'], 'single quotes keep spaces');
eq(sp("'a\\b'"), ['a\\b'], 'backslash literal inside single quotes');
eq(sp('"a\\"b"'), ['a"b'], 'escaped quote inside double quotes');
eq(sp('"a\\nb"'), ['a\\nb'], 'backslash before ordinary char stays literal in double quotes');
eq(sp('a\\ b'), ['a b'], 'escaped space outside quotes');
eq(sp('a"b"c'), ['abc'], 'adjacent runs join');
eq(sp("x''y"), ['xy'], 'empty quotes join');
eq(sp("''"), [''], 'lone empty quotes make an empty arg');
eq(sp('cmd --flag="a b" pos'), ['cmd', '--flag=a b', 'pos'], 'realistic');
eq(sp('"$HOME"'), ['$HOME'], 'no variable expansion');
eq(sp('"a\\$b"'), ['a$b'], 'escaped dollar');
for (const bad of ['"unterminated', "'unterminated", 'trailing\\']) {
  let threw = false; try { sp(bad); } catch (e) { threw = true; }
  if (!threw) { console.error('must throw on', S(bad)); process.exit(1); }
}
console.log('ok');
VERIFYJS
